def norm(mask):
 mr=min(r for r,c in mask); mc=min(c for r,c in mask)
 return frozenset((r-mr,c-mc) for r,c in mask)
def rot90(mask): return norm([(-c,r) for r,c in mask])
def refl(mask): return norm([(r,-c) for r,c in mask])
